INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2013-06-24 10:52:04', '2013-06-24 10:52:04', 'In cadrul acestui proiect sunt ilustrate mai multe categorii de medicamente care sunt folosite pentru a trata diverse tipuri de afectiuni.', 'Proiect licenta', '', 'publish', 'open', 'open', '', 'hello-world', '', '', '2013-06-24 15:06:51', '2013-06-24 15:06:51', '', 0, 'http://localhost/Produse%20Farmaceutice/?p=1', 0, 'post', '', 1),
(2, 1, '2013-06-24 10:52:04', '2013-06-24 10:52:04', 'Afectiunile digestive sunt probleme complexe care au etiologie si simptomatologie specifice, insa multe persoane au inceput sa identifice o relatie de cauza-efect intre anumite alimente sau activitati si acestea. Cele mai vehiculate mituri sunt acelea in care se crede ca guma de mestecat inghitita se lipeste de stomac, ca mancarurile picante provoaca ulcer, ca fumatul combate arsurile stomacale sau ca daca nu ai simptome inseamna ca nu poti avea cancer de colon.\r\n<h2><strong>Din aceasta categorie fac parte:</strong></h2>\r\n- <a title=\"Afectiuni digestive\" href=\"http://localhost/Produse%20Farmaceutice/?page_id=13\">Afectiuni gastrice</a>\r\n\r\n- <a title=\"Antidiareicele\" href=\" http://localhost/Produse%20Farmaceutice/?page_id=56\">Antidiareice</a>\r\n\r\n- <a title=\"Constipatia\" href=\"http://localhost/Produse%20Farmaceutice/?page_id=66\">Constipatie</a>\r\n\r\n- <a title=\"Colici Copii\" href=\"http://localhost/Produse%20Farmaceutice/?page_id=72\">Colici copii</a>', 'Afectiuni digestive', '', 'publish', 'open', 'open', '', 'sample-page', '', '', '2013-06-24 14:21:44', '2013-06-24 14:21:44', '', 0, 'http://localhost/Produse%20Farmaceutice/?page_id=2', 0, 'page', '', 0),
(3, 1, '2013-06-24 10:52:17', '0000-00-00 00:00:00', '', 'Auto Draft', '', 'auto-draft', 'open', 'open', '', '', '', '', '2013-06-24 10:52:17', '0000-00-00 00:00:00', '', 0, 'http://localhost/Produse%20Farmaceutice/?p=3', 0, 'post', '', 0),
(4, 1, '2013-06-24 15:07:53', '2013-06-24 15:07:53', 'In cadrul acestui proiect sunt ilustrate mai multe categorii de medicamente care sunt folosite pentru a trata diverse tipuri de afectiuni.', 'Proiect licenta', '', 'inherit', 'open', 'open', '', '1-autosave', '', '', '2013-06-24 15:07:53', '2013-06-24 15:07:53', '', 1, 'http://localhost/Produse%20Farmaceutice/?p=4', 0, 'revision', '', 0),
(5, 1, '2013-06-24 12:23:40', '2013-06-24 12:23:40', 'Produse farmaceutice in categoria Afectiuni digestive:\n\n- Afectiuni gastrice\n\n- Antidiareice\n\n- Constipatie\n\n- Colici copii\n\n- Antispastice\n\n- Enzime digestive', 'Afectiuni digestive', '', 'inherit', 'open', 'open', '', '2-autosave', '', '', '2013-06-24 12:23:40', '2013-06-24 12:23:40', '', 2, 'http://localhost/Produse%20Farmaceutice/?p=5', 0, 'revision', '', 0),
