INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(3, 'American Gangster', 2007, 'Actiune Biografie', 158, 3, 'Denzel Washington , Russel Crowe ,Cuba Gooding Jr.', 'Steven Zaillian', 'Detectivul Richie Roberts (Russell Crowe) are o sarcina: sa curete strazile New York-ului de puternicii traficanti de droguri', 11, 1, 1, , 'https://youtu.be/BV_nssS6Zkg');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(4, 'Blow', 2001, 'Drama', 124, 3, 'Johnny Depp , Penelope Cruz ,Franka Potente', 'Ted Demme', 'Visul Alb dezvaluie povestea fascinanta a lui George Jung  urcusul si caderea  despre felul in care acesta si-a folosit si ultima picatura de ingeniozitate, ambitie si curaj doar pentru a-si vedea toate visurile innecate in lacomie. ', 20, 0, 0, , 'https://youtu.be/scWkP1GdnuU');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(5, 'Brothers', 2009, 'Drama Thriller', 110, 3, 'Jake Gyllenhaal ,Natalie Portman ,Tobey Maguire', 'Jim Sheridan', 'Dupa ce elicopterul lui Sam Cahill este doborat in muntii Pamir, iar soldatul este dat disparut si considerat mort, Tommy si Grace devin constienti de atractia fizica reciproca, desi sunt speriati si rusinati in acelasi timp de sentimentele tot mai puternice pe care le dezvolta unul fata de celalalt.', 14, 1, 1, , 'https://youtu.be/gnkqEIoN9wc');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(6, 'Deepwater Horizon', 2016, 'Drama Thriller', 107, 1, 'Mark Wahlberg ,Kurt Russell ,Kate Hudson', 'Peter Berg', 'O explozie de proportii a avut loc in 20 aprilie 2010, la 1.500 m in Golful Mexic, la 80 km de Venice (Louisiana). Putul de petrol ce perfora platforma Deepwater Horizon a fost distrus de teribilul accident ce a ucis 11 lucratori, ranind alti 17. Mii de barili de petrol au inceput sa fie eliberatii zilnic din put, iar \"mareea neagra\" ce a acoperit Golful si-a extins bratele distrugatoare spre restul apelor lumii, riscand sa afecteze pe termen lung animalele, viata omului, chiar si industria.', 30, 0, 0, , 'https://youtu.be/8yASbM8M2vg');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(7, 'Fences', 2016, 'Drama', 139, 3, 'Denzel Washington ,Viola Davis', 'Denzel Washington', 'SUA, anii \'50. Un tata afro-american se confrunta cu problemele obisnuite pe care le au oamenii de culoare generate de rasism. Acesta incearca sa-si intretina familia si sa le dea copiilor sai o educatie cat se poate de buna.', 31, 1, 1, , 'https://youtu.be/vylWibtgdbU');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(8, 'Focus', 2015, 'Actiune', 105, 2, 'Will Smith ,Margot Robbie', 'John Requa', 'Will Smith joaca rolul lui Nicky, un maestru al inselaciunilor, care se indragosteste de o novice, Jess (Margot Robbie). In timp ce o invata trucurile meseriei, ea se apropie un pic prea mult, iar el se rupe de ea. Trei ani mai tarziu, fosta flama, acum o adevarata femeie fatala, apare la Buenos Aires, in mijlocul unei curse cu miza mare. In mijlocul celei mai noi si mai periculoase scheme a lui Nick, ea vine si-i da planurile peste cap si-l scoate oarecum din joc pe maestrul escroc.', 21, 0, 0, , 'https://youtu.be/MxCRgtdAuBo');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(9, 'Fury', 2014, 'Actiune Razboi', 134, 3, 'Bradd Pitt ,Shia LaBeouf ,Jon Bernthal', 'David Ayer', 'Povestea ne poarta in aprilie 1945, la sfarsitul celui de-Al Doilea Razboi Mondial, iar in centrul atentiei este Wardaddy (Brad Pitt), un sergent american cu mare experienta in lupta. Impreuna cu echipajul sau de cinci oameni, Wardaddy conduce un tank Sherman supranumit Fury si patrunde in spatele liniilor inamice pentru o misiune cvasi-sinucigasa care ar trebui sa dea ultima lovitura fortelor armate ale Germaniei naziste.', 39, 1, 1, , 'https://youtu.be/-OGvZoIrXpg');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(10, 'Hacksaw Ridge', 2016, 'Actiune Razboi', 129, 3, 'Andrew Garfield, Vince Vaughn, Luke Bracey', 'Mel Gibson', 'Filmul se concentreaza pe batalia de la Okinawa din 1945, unde Doss s-a ocupat de unul singur de 75 de raniti, chiar sub focul inamic.', 40, 0, 0, , 'https://youtu.be/s2-1hz1juBI');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(11, 'Menace II Society', 1993, 'Actiune Drama', 104, 4, 'Tyrin Turner, Larenz Tate, Jada Pinkett Smith', 'Albert Hughes', 'Un tanar hustler de strada incearca sa scape de rigorile si ispitele ghetoului intr-o cautare pentru o viata mai buna.Dar tot ce face este sa mearga printr-un calvar de arme, droguri si violenta prin mahalale.', 20, 0, 0, , 'https://youtu.be/ZHle3FQbWmw');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(12, 'Notorious', 2009, 'Actiune Biografie', 129, 4, 'Jamal Woolard, Naturi Naughton, Derek Luke', ' George Tillman Jr.', 'Povestea pe viata si pe moarte a lui Notorius B.I.G.(a.k.a. Christopher Wallace), care a venit direct din Brooklyn sa ia pe sus lumea Hip-hop-ului.', 25, 0, 0, , 'https://youtu.be/kDDv6pAbN_U');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(13, 'Straight Outta Compton', 2015, 'Actiune Drama', 167, 4, 'O\'Shea Jackson Jr., Jason Mitchell, Corey Hawkins', 'F. Gary Gray', 'Productia biografica Straight Outta Compton descrie ascensiunea trupei de hip hop N.W.A. din California - alcatuita din nume ajunse celebre, precum Dr. Dre, Ice Cube, Eazy-E si MC Ren - si succesul fulminant al acesteia in industria muzicala. Trupa a marcat inceputul unei noi ere a gangsta rap-ului, cu modificari inovatoare la nivelul productiei si versurilor, ce contineau critici la adresa societatii si a conducerii.', 40, 0, 0, , 'https://youtu.be/rsbWEF1Sju0');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(14, 'The Accountant', 2016, 'Actiune Drama', 128, 3, 'Ben Afflek, Anna Kendrick, Jon Bernthal', 'Gavin O\'Connor', 'Sub o acoperire anosta, Christian tine contabilitatea unora dintre cele mai periculoase organizatii criminale din lume. In momentul in care autoritatile ajung pe urmele lui, acesta isi ofera serviciile unui client legitim: o companie de robotica in al carui bilant apar discrepante de milioane de dolari. Lupta pentru supravietuire incepe atunci cand Chstistian descopera neregulile financiare din firma.', 50, 0, 0, , 'https://youtu.be/DBfsgcswlYQ');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(15, 'The gift', 2015, 'Drama', 108, 3, 'Joel Edgerton, Jason Bateman, Rebecca Hall', 'Joel Edgerton', 'Simon si Robyn au o viata perfecta. Totul se schimba cand cei doi il intalnesc pe Gordo, o cunostinta din liceu a lui Simon. Barbatul se insinueaza in viata cuplului, iar curand se va vedea ca intentiile sale nu sunt dintre cele mai bune.', 30, 0, 0, , 'https://youtu.be/I3IiZU9JBuE');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(16, 'The town', 2010, 'Actiune Drama', 125, 3, 'Ben Afflek, Rebecca Hall, Jeremy Renner', 'Ben Affleck', 'In fiecare an, in Boston au loc peste 300 de jafuri bancare.Si un singur cartier, Charlestown, a dat lumii mai multi spargatori de banci si hoti de masini decat oricare alt loc din America.', 40, 0, 0, , 'https://youtu.be/WcXt9aUMbBk');
INSERT INTO `filme` (`IdFilm`, `Titlu`, `AnLansare`, `Gen`, `Durata`, `IdLimitavarsta`, `Actori`, `Regia`, `Descriere`, `StocEfectiv`, `Bucati_Inchiriate`, `Nr_Inchirieri`, `Imagine`, `Trailer`) VALUES
(17, 'Training Day', 2001, 'Actiune Drama', 122, 4, 'Denzel Washington, Eva Mendez, Ethan Hawke, Snoop Dogg', 'Antoine Fuqua', 'Zi de instructie ii urmareste activitatea lui Alonzo pe masura ce acesta il pune la incercare pe debutantul in meserie idealist, Jake Hoyt (ETHAN HAWKE), care are la dispozitie o zi si doar o zi pentru a-i dovedi ce poate sa faca superiorului sau carismatic, dar de temut. Pe parcursul urmatoarelor 24 de ore, Jake va fi influentat din ce in ce mai mult de logica stramba a lui Alonzo in timp ce amandoi isi vor risca vietile si carierele, fiecare intelegand in felul sau notiunea de a face dreptate.', 30, 0, 0, , 'https://youtu.be/gKTVQPOH8ZA');
