INSERT INTO `filme` (`IdFilm`, `TitluOriginal`, `TitluTradus`, `AnLansare`, `Gen`, `Durata`, `IdRating`, `Actori`, `Regia`, `Descriere`, `TaraProducatoare`, `StocEfectiv`, `Bucati_Inchiriate`) VALUES
(1, 'ARGO', 'ARGO', 2012, 'Drama Istoric Thriller', 120, 2, 'Bryan Cranston, Ben Affleck, Clea DuVall, John Goodman, Alan Arkin', 'Ben Affleck', 'A dramatization of the 1980 joint CIA-Canadian secret operation to extract six fugitive American diplomatic personnel out of revolutionary Iran.', 'USA', 5, 0),
(2, 'Fast &  Furious 6', 'Furios si iute 6', 2013, 'Actiune Crima Thriller', 13, 2, 'Dwayne Johnson, Vin Diesel, Paul Walker, Michelle Rodriguez', 'Justin Lin', 'De cand Dom (Vin Diesel) si Brian (Paul Walker) au dat lovitura de la Rio impotriva imperiului condus de un escroc de talie internatioanla, aducand in seiful echipei 100 de milioane de dolari, eroii nostri s-au preumblat pe tot globul. Dar, pentru ca nu se pot intoarce acasa ca sa traiasca linistiti din acei bani, sunt acum nemultumiti si simt ca le lipseste ceva', 'USA', 9, 2),
(3, 'Epic', 'Regatul Secret', 2013, 'Aventura Animatie Familie Fantastic', 102, 1, 'Amanda Seyfried, Josh Hutcherson, Colin Farrell, BeyoncÃ© Knowles', 'Chris Wedge', 'A teenager finds herself transported to a deep forest setting where a battle between the forces of good and the forces of evil is taking place. She bands together with a rag-tag group characters in order to save their world -- and ours.', 'CANADA', 7, 0),
(4, 'Toate pinzele sus - Secretul epavei', 'Toate pinzele sus - Secretul epavei', 1987, 'Aventura Comedie', 87, 1, 'Sebastian Papaiani, Ion Besoiu, Ilarion Ciobanu', 'Mircea Muresan', 'Filmul prezinta aventurile a doi prieteni, romanul Lupan si francezul Vaillant, porniti pe urmele secretelor epavei corabiei L\'Esperance.', 'ROMANIA', 0, 2),
(13, 'Devil', 'Demon', 2010, 'Groaza Thriller', 80, 4, 'Geoffrey Arend, Bojana Novakovic, Chris Messina, Bokeem Woodbine', 'John Erick Dowdle', 'Intr-o zi aparent obisnuita, intr-o cladire de birouri cu multe etaje, un grup de cinci persoane care s-au intalnit absolut intamplator si care nu se cunosc intre ele raman blocate intr-un ascensor al groazei. Doua femei si trei barbati sunt prinsi ca intr-o capcana intre peretii ingusti ai unui lift, oprit intre etaje din cauza unei pene de curent, sub privirile neputincioase ale agentilor de securitate, care fac tot posibilul ca sa-i salveze.', 'USA', 3, 0);
